import{_ as i,o as a,c as o,a2 as l}from"./chunks/framework.BN2sqjC1.js";const p=JSON.parse('{"title":"Checklist di rilascio 1.0.0 (M7-WP5)","description":"","frontmatter":{},"headers":[],"relativePath":"release/v1.0.0-checklist.md","filePath":"release/v1.0.0-checklist.md"}'),c={name:"release/v1.0.0-checklist.md"};function r(t,e,d,n,s,u){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="checklist-di-rilascio-1-0-0-m7-wp5" tabindex="-1">Checklist di rilascio 1.0.0 (M7-WP5) <a class="header-anchor" href="#checklist-di-rilascio-1-0-0-m7-wp5" aria-label="Permalink to &quot;Checklist di rilascio 1.0.0 (M7-WP5)&quot;">​</a></h1><p>Il codice della candidata <code>1.0.0-rc.1</code> è pronto e verificato in locale (test, lint, e2e, scansioni). Questa checklist elenca ciò che <strong>non si può fare da un ambiente di sviluppo</strong> e che blocca il tag <code>v1.0.0</code>. Segnare <code>[x]</code> con data e responsabile.</p><h2 id="_1-decisioni-dell-owner" tabindex="-1">1. Decisioni dell&#39;owner <a class="header-anchor" href="#_1-decisioni-dell-owner" aria-label="Permalink to &quot;1. Decisioni dell&#39;owner&quot;">​</a></h2><ul><li>[x] <strong>Nome del prodotto</strong>: rebrand a &quot;MemoBrain Notes&quot; eseguito (identificatori <code>memobrain</code>, cartella <code>.memobrain/</code>, schema <code>memobrain://</code>, realm Keycloak, proto <code>memobrain.v1</code>; vedi <code>docs/release/rebrand-inventory.md</code>). Restano da fare logo/icone, certificati di firma, dominio pubblico e <code>Specifications.md</code> (a cura dell&#39;owner).</li><li>[ ] Recepire nello spec le deviazioni proposte negli ADR (0008–0025), in particolare gli endpoint GDPR (<code>GET /me/export</code>, <code>DELETE /me</code>), il build con esbuild (ADR-0025) e la parità con i plugin Excalidraw (ADR-0024: §2.7, §2.4, matrice funzioni; elenco puntuale nell&#39;ADR); il rebrand &quot;Nodus&quot; dello spec.</li><li>[ ] Politica di conservazione dell&#39;audit log (oggi senza scadenza, vedi <code>docs/security/data-retention.md</code>) e cancellazione dell&#39;account Keycloak alla cancellazione GDPR (oggi l&#39;account è solo disabilitato).</li></ul><h2 id="_2-credenziali-e-firma-docs-release-secrets-md" tabindex="-1">2. Credenziali e firma (<code>docs/release/secrets.md</code>) <a class="header-anchor" href="#_2-credenziali-e-firma-docs-release-secrets-md" aria-label="Permalink to &quot;2. Credenziali e firma (`docs/release/secrets.md`)&quot;">​</a></h2><ul><li>[ ] Generare la chiave ed25519 degli aggiornamenti; incorporare la chiave pubblica di rilascio (<code>UPDATE_PUBLIC_KEY</code>) e conservare quella privata fuori dal repository.</li><li>[ ] Certificato Authenticode (Windows) e Apple Developer ID con credenziali <code>notarytool</code> (macOS) configurati nei segreti del repository.</li><li>[ ] Prima esecuzione reale di <code>release.yml</code> in <code>workflow_dispatch</code> (dry-run) e poi su un tag <code>v1.0.0-rc.N</code>: verificare artefatti, firma, notarizzazione, <code>SHA256SUMS</code>, manifest firmato, immagine OCI firmata (cosign) e chart.</li><li>[ ] Sostituire l&#39;icona dell&#39;app (oggi <code>appicon.png</code> provvisoria) e gli URL <code>example</code> nel chart, in AppStream e in nfpm.</li></ul><h2 id="_3-test-manuale-cross-os" tabindex="-1">3. Test manuale cross-OS <a class="header-anchor" href="#_3-test-manuale-cross-os" aria-label="Permalink to &quot;3. Test manuale cross-OS&quot;">​</a></h2><p>Su macOS, Windows e Linux (installer reale, non <code>wails dev</code>):</p><ul><li>[ ] <code>docs/qa/obsidian-parity.md</code>, sezioni M1 e M6 (webview reale: hover, stampa PDF, selettori nativi, grafo a 10k nodi ≥ 30 fps).</li><li>[ ] <code>docs/qa/m3-drawings-canvas.md</code>, <code>m4-sharing.md</code>, <code>m5-admin-export.md</code>, <code>m6-search-export.md</code>.</li><li>[ ] Registrazione dello schema URL (<code>memobrain://…</code>) e login con redirect loopback e con fallback.</li><li>[ ] Aggiornamento automatico: installare la <code>rc.1</code>, pubblicare la <code>rc.2</code> firmata, verificare &quot;Aggiornamento disponibile&quot; e applicazione su ciascun OS.</li><li>[ ] Prestazioni di avvio a freddo (&lt; 3 s) e latenza di digitazione su una nota da 1 MB, sul webview reale.</li></ul><h2 id="_4-accessibilita" tabindex="-1">4. Accessibilità <a class="header-anchor" href="#_4-accessibilita" aria-label="Permalink to &quot;4. Accessibilità&quot;">​</a></h2><ul><li>[ ] Test con screen reader: VoiceOver (macOS), NVDA e Narrator (Windows), Orca (Linux), con <code>docs/qa/a11y-desktop.md</code> e <code>docs/qa/a11y-web.md</code>.</li><li>[ ] Alternative testuali: <strong>disegni fatti</strong> (comando «Descrivi il disegno come testo»); per grafo e canvas ancora assenti: progettarle oppure dichiarare il limite nelle note di rilascio (già nel CHANGELOG).</li></ul><h2 id="_5-sicurezza" tabindex="-1">5. Sicurezza <a class="header-anchor" href="#_5-sicurezza" aria-label="Permalink to &quot;5. Sicurezza&quot;">​</a></h2><ul><li>[ ] Audit esterno del progetto crittografico (<code>docs/security/crypto-design.md</code>) e pen test (<code>docs/security/pentest-scope.md</code>); trattare i risultati prima del tag.</li><li>[ ] Prima esecuzione di <code>security.yml</code> su GitHub (versioni di gitleaks, syft, licenze non verificate in locale).</li><li>[ ] Verificare in un ambiente reale che <code>/metrics</code> non sia raggiungibile dall&#39;ingress pubblico e che il TLS e gRPC su HTTP/2 funzionino dietro il proxy scelto.</li><li>[x] Realm di produzione senza utenti di prova né <code>dev-admin-svc-secret</code>: <code>deploy/keycloak-prod/realm-memobrain.json</code> (secret e origine web da ambiente, verificato con Keycloak 26.7) è quello importato da <code>deploy/compose</code>. <code>/metrics</code> non è raggiungibile via ingress (<code>metricsguard_test.go</code>). Per un Keycloak esterno (Helm) resta da fare a mano.</li></ul><h2 id="_6-affidabilita-e-prestazioni" tabindex="-1">6. Affidabilità e prestazioni <a class="header-anchor" href="#_6-affidabilita-e-prestazioni" aria-label="Permalink to &quot;6. Affidabilità e prestazioni&quot;">​</a></h2><ul><li>[ ] Ripetere il chaos test su un cluster rappresentativo (PostgreSQL ad alta disponibilità, almeno 2 repliche, finestra di ore) per sostenere il 99,9 %.</li><li>[ ] Prova di ripristino su dati realistici: misurare RTO/RPO veri (la prova automatica usa un dataset minimo) e provare Keycloak.</li><li>[ ] Prima esecuzione manuale della suite di prestazioni (<code>task perf</code>; il workflow notturno è stato rimosso) e del carico k6 (1.000 utenti, mai eseguito): salvare la baseline CI in <code>docs/perf/baseline-ci-&lt;note&gt;.json</code>.</li><li>[ ] Decidere se la ricerca con espressioni regolari su 50k note (461 ms) è accettabile o se serve un prefiltro letterale.</li></ul><h2 id="_7-rilascio" tabindex="-1">7. Rilascio <a class="header-anchor" href="#_7-rilascio" aria-label="Permalink to &quot;7. Rilascio&quot;">​</a></h2><ul><li>[x] Aggiornare <code>CHANGELOG.md</code> (sezione <code>## [1.0.0]</code>, datata 2026-10-28) e togliere &quot;non rilasciata&quot;.</li><li>[ ] Creare il tag <code>v1.0.0</code> (<code>git tag -s v1.0.0</code>) <strong>su richiesta esplicita dell&#39;owner</strong>; il workflow produce la release in bozza; pubblicarla dopo il controllo degli artefatti.</li><li>[ ] Annunciare il canale di aggiornamento e archiviare chiavi e baseline.</li></ul>',17)])])}const g=i(c,[["render",r]]);export{p as __pageData,g as default};
